questionvariables.text:
tris : [ [[0,0],[11,0],[-1,4]], [[0,0],[11,0],[0,5]], [[0,0],[10,0],[-1,5]], [[0,0],[9,0],[-1,4]], [[0,0],[11,0],[2,4]], [[0,0],[11,0],[-1,6]], [[0,0],[10,0],[0,4]], [[0,0],[11,0],[1,6]], [[0,0],[10,0],[2,4]], [[0,0],[11,0],[2,5]] ];
tri : tris[rand(length(tris))+1];
A : tri[1] + [-1,-1];
B : tri[2] + [-1,-1];
C : tri[3] + [-1,-1];
/* side lengths, each opposite its like-named vertex */
la : Distance(B,C);  /* a = |BC|, opposite A */
lb : Distance(A,C);  /* b = |CA|, opposite B */
lc : Distance(A,B);  /* c = |AB|, opposite C */
perim : la+lb+lc;
ssemi : perim/2;
area : abs(A[1]*(B[2]-C[2])+B[1]*(C[2]-A[2])+C[1]*(A[2]-B[2]))/2;
/* B-excentre = (a*A - b*B + c*C)/(a - b + c)  (target answer) */
denB : la-lb+lc;
ta_EB : [(la*A[1]-lb*B[1]+lc*C[1])/denB, (la*A[2]-lb*B[2]+lc*C[2])/denB];
/* exradius opposite B: r_B = area/(s - b) */
ta_RB : area/(ssemi-lb);
/* distractor centres used only for misconception feedback */
ta_X : [(la*A[1]+lb*B[1]+lc*C[1])/perim, (la*A[2]+lb*B[2]+lc*C[2])/perim];   /* incentre: all internal bisectors */
denA : -la+lb+lc;
ta_EA : [(-la*A[1]+lb*B[1]+lc*C[1])/denA, (-la*A[2]+lb*B[2]+lc*C[2])/denA];   /* excentre opposite A */
denC : la+lb-lc;
ta_EC : [(la*A[1]+lb*B[1]-lc*C[1])/denC, (la*A[2]+lb*B[2]-lc*C[2])/denC];   /* excentre opposite C */
/* inradius, used only to detect the wrong radius in feedback */
ta_inr : area/ssemi;
/* circumcentre and circumradius, used only to detect this misconception */
ddet : 2*(A[1]*(B[2]-C[2])+B[1]*(C[2]-A[2])+C[1]*(A[2]-B[2]));
ta_O : [((A[1]^2+A[2]^2)*(B[2]-C[2])+(B[1]^2+B[2]^2)*(C[2]-A[2])+(C[1]^2+C[2]^2)*(A[2]-B[2]))/ddet, ((A[1]^2+A[2]^2)*(C[1]-B[1])+(B[1]^2+B[2]^2)*(A[1]-C[1])+(C[1]^2+C[2]^2)*(B[1]-A[1]))/ddet];
ta_Rc : sqrt((ta_O[1]-A[1])^2+(ta_O[2]-A[2])^2);
/* rounded model answers (to 3 d.p.), used for the inputs and the question tests */
rnd3(z) := float(round(float(z)*1000)/1000);
ans_xc : rnd3(ta_EB[1]);
ans_yc : rnd3(ta_EB[2]);
ans_r  : rnd3(ta_RB);
ans_Xx : rnd3(ta_X[1]);
ans_Xy : rnd3(ta_X[2]);
ans_EAx : rnd3(ta_EA[1]);
ans_EAy : rnd3(ta_EA[2]);
ans_ECx : rnd3(ta_EC[1]);
ans_ECy : rnd3(ta_EC[2]);
ans_ir : rnd3(ta_inr);
ans_Ox : rnd3(ta_O[1]);
ans_Oy : rnd3(ta_O[2]);
ans_Rc : rnd3(ta_Rc);

feedbackvariables.text:
/* largest single-coordinate error, so x AND y must each be correct to 3 d.p. */
errEB  : max(abs(xc-ta_EB[1]), abs(yc-ta_EB[2]));
errInc : max(abs(xc-ta_X[1]), abs(yc-ta_X[2]));
errEA  : max(abs(xc-ta_EA[1]), abs(yc-ta_EA[2]));
errEC  : max(abs(xc-ta_EC[1]), abs(yc-ta_EC[2]));
errCirc: max(abs(xc-ta_O[1]), abs(yc-ta_O[2]));
